import { describe, expect, it } from 'vitest';
import {
  FREE_FOR_ALL,
  HARBOUR_FORT_ARENA,
  HARBOUR_FORT_BOOK_SPOTS,
  HARBOUR_FORT_HEIGHT,
  HARBOUR_FORT_SPAWNS,
  HARBOUR_FORT_WALLS,
  HARBOUR_FORT_WIDTH,
  createFuMatch,
  stepFu,
} from '../src/rules';
import { circleHitsWalls, wallsOf } from '../src/rules/arena';
import { DT, R, at, input, make } from './support/fixtures';

// harbour_fort: the second map reconstructed from the master gameplay video (shot S9), as DATA owned by the rules (generated by
// art/reconstruction/runtime/gen_arena_proxies.py from the measured proxy kit). The moat only blocks: no water mechanic exists
// (GAMEPLAY INTERACTION: DEFERRED). These tests check the data; the approved mechanics are unchanged.

const walls = wallsOf(HARBOUR_FORT_ARENA);

describe('harbour_fort: the arena data', () => {
  it('is a 1560 × 940 arena of solid structures and blocking water, six spawns and no Slice 6 systems', () => {
    expect([HARBOUR_FORT_WIDTH, HARBOUR_FORT_HEIGHT]).toEqual([1560, 940]);
    expect([HARBOUR_FORT_ARENA.width, HARBOUR_FORT_ARENA.height]).toEqual([1560, 940]);
    expect(HARBOUR_FORT_ARENA.spawns).toHaveLength(6);
    expect(HARBOUR_FORT_ARENA.gates ?? []).toEqual([]);
    expect(HARBOUR_FORT_ARENA.platforms ?? []).toEqual([]);
    expect(HARBOUR_FORT_ARENA.hazards ?? []).toEqual([]);
    expect(walls).toHaveLength(HARBOUR_FORT_WALLS.length);
    expect(new Set(HARBOUR_FORT_WALLS.map((w) => w.kind))).toEqual(new Set(['SOLID', 'WATER']));
    expect(createFuMatch([{ id: 'a', slot: 0 }], { arena: HARBOUR_FORT_ARENA }).config.arena).toBe(
      HARBOUR_FORT_ARENA,
    );
  });

  it('every obstacle lies inside the boundary, has a positive size and a unique id', () => {
    expect(new Set(HARBOUR_FORT_WALLS.map((w) => w.id)).size).toBe(HARBOUR_FORT_WALLS.length);
    for (const w of HARBOUR_FORT_WALLS) {
      expect(w.width, w.id).toBeGreaterThan(0);
      expect(w.height, w.id).toBeGreaterThan(0);
      expect(w.x, w.id).toBeGreaterThanOrEqual(0);
      expect(w.y, w.id).toBeGreaterThanOrEqual(0);
      expect(w.x + w.width, w.id).toBeLessThanOrEqual(HARBOUR_FORT_WIDTH);
      expect(w.y + w.height, w.id).toBeLessThanOrEqual(HARBOUR_FORT_HEIGHT);
    }
  });

  it('every spawn and Book spot is on open floor with room around it; spawns are well spread', () => {
    for (const p of [...HARBOUR_FORT_SPAWNS, ...HARBOUR_FORT_BOOK_SPOTS]) {
      expect(circleHitsWalls(p, R + 20, walls), `${p.x},${p.y}`).toBe(false);
      expect(p.x - R).toBeGreaterThan(0);
      expect(p.y - R).toBeGreaterThan(0);
      expect(p.x + R).toBeLessThan(HARBOUR_FORT_WIDTH);
      expect(p.y + R).toBeLessThan(HARBOUR_FORT_HEIGHT);
    }
    for (let i = 0; i < 6; i += 1)
      for (let j = i + 1; j < 6; j += 1) {
        const a = HARBOUR_FORT_SPAWNS[i];
        const b = HARBOUR_FORT_SPAWNS[j];
        expect(Math.hypot((a?.x ?? 0) - (b?.x ?? 0), (a?.y ?? 0) - (b?.y ?? 0))).toBeGreaterThan(
          300,
        );
      }
  });

  it('six-player fuzz with the approved mechanics never puts a living body inside an obstacle or outside the boundary', () => {
    const IDS = ['a', 'b', 'c', 'd', 'e', 'f'];
    let s = make(IDS, { arena: HARBOUR_FORT_ARENA, ...FREE_FOR_ALL, seed: 11 });
    for (let i = 0; i < 2400; i += 1) {
      s = stepFu(
        s,
        input(
          Object.fromEntries(
            IDS.map((id, k) => [
              id,
              {
                move: { x: Math.cos(i / (11 + 2 * k) + k), y: Math.sin(i / (13 + k) + 2 * k) },
                dash: (i + 3 * k) % 17 === 0,
                throw: (i + 5 * k) % 37 === 0,
                slash: (i + 2 * k) % 41 === 0,
              },
            ]),
          ),
        ),
        DT,
      ).state;
      for (const p of s.players) {
        if (!p.alive) continue;
        const pos = at(s, p.id);
        expect(circleHitsWalls(pos, R - 0.01, walls), `tick ${i} ${p.id}`).toBe(false);
        expect(pos.x).toBeGreaterThanOrEqual(R - 1e-6);
        expect(pos.y).toBeGreaterThanOrEqual(R - 1e-6);
        expect(pos.x).toBeLessThanOrEqual(HARBOUR_FORT_WIDTH - R + 1e-6);
        expect(pos.y).toBeLessThanOrEqual(HARBOUR_FORT_HEIGHT - R + 1e-6);
      }
    }
  });
});
